// Changed-file execution gate. Coverage proves execution only; it does not prove expectation
// quality. CI passes --reports to reuse LCOV generated by the complete tier run.
import { execFileSync, spawnSync } from "node:child_process";
import { existsSync, readFileSync } from "node:fs";
import path from "node:path";

import {
  groupSourceFilesByPackage,
  listChangedFiles,
  readOption,
  resolveBaseRef,
} from "./changed-source-files.mjs";

const GUIDE = "docs/testing/README.md";
const TIERS = ["unit", "integration", "transport"];
const baseRef = resolveBaseRef(readOption("base"));
const groups = groupSourceFilesByPackage(listChangedFiles(baseRef));
const reportsOnly = process.argv.includes("--reports");
const failures = [];
const mergeBase = git(["merge-base", baseRef, "HEAD"]);

for (const [packageDirectory, files] of groups) {
  const manifest = JSON.parse(readFileSync(path.join(packageDirectory, "package.json"), "utf8"));
  const packageTiers = TIERS.filter((tier) =>
    tier === "unit" ? Boolean(manifest.scripts?.test) : Boolean(manifest.scripts?.[`test:${tier}`]),
  );
  if (!reportsOnly) runCoverage(packageDirectory, manifest.name, packageTiers);
  const coverage = readCoverage(packageDirectory, packageTiers);
  for (const file of files) {
    const source = path.resolve(packageDirectory, file);
    const changed = changedLines(`${packageDirectory}/${file}`, mergeBase);
    const executable = coverage.get(source) ?? new Map();
    const changedExecutable = [...changed].filter((line) => executable.has(line));
    if (changedExecutable.some((line) => executable.get(line) === 0)) {
      failures.push(`${packageDirectory}/${file} (changed executable lines uncovered)`);
    }
  }
}

if (groups.size === 0) {
  process.stdout.write(`No changed source files (base: ${baseRef}).\n`);
} else if (failures.length > 0) {
  process.stderr.write(
    `Changed source files not executed by tests:\n${failures.map((file) => `  ${file}\n`).join("")}` +
      `Coverage proves execution, not assertion strength. See ${GUIDE}.\n`,
  );
  process.exitCode = 1;
} else {
  process.stdout.write("Coverage gate passed: every changed executable line was exercised.\n");
}

function runCoverage(packageDirectory, packageName, tiers) {
  for (const tier of tiers) {
    const task = tier === "unit" ? "test" : `test:${tier}`;
    const result = spawnSync(
      "pnpm",
      ["exec", "turbo", "run", task, `--filter=${packageName}`, "--force", "--concurrency=1"],
      { env: { ...process.env, CI: "true" }, stdio: "inherit" },
    );
    if (result.status !== 0) {
      process.stderr.write(
        `${packageDirectory} ${tier}: tests or environment failed before coverage; ` +
          `this is not an uncovered-code finding. See ${GUIDE}.\n`,
      );
      process.exit(result.status ?? 1);
    }
  }
}

function readCoverage(packageDirectory, tiers) {
  const lines = new Map();
  for (const tier of tiers) {
    const report = path.join(packageDirectory, "coverage", tier, "lcov.info");
    if (!existsSync(report)) reportError(`Missing LCOV report: ${report}`);
    mergeLcov(lines, readFileSync(report, "utf8"), packageDirectory, report);
  }
  return lines;
}

function mergeLcov(files, contents, packageDirectory, report) {
  let currentFile;
  let sawRecord = false;
  let sawLineSummary = false;
  for (const line of contents.split("\n")) {
    if (line.startsWith("SF:")) {
      currentFile = path.resolve(packageDirectory, line.slice(3));
      sawRecord = true;
    } else if (line.startsWith("DA:")) {
      const [lineText, hitsText] = line.slice(3).split(",");
      const lineNumber = Number(lineText);
      const hits = Number(hitsText);
      if (
        !currentFile ||
        !Number.isInteger(lineNumber) ||
        lineNumber < 1 ||
        !isNonnegativeInteger(hits)
      ) {
        reportError(`Malformed LCOV report: ${report}`);
      }
      const coveredLines = files.get(currentFile) ?? new Map();
      coveredLines.set(lineNumber, Math.max(coveredLines.get(lineNumber) ?? 0, hits));
      files.set(currentFile, coveredLines);
    } else if (line.startsWith("LH:")) {
      if (!currentFile || !/^LH:\d+$/u.test(line)) reportError(`Malformed LCOV report: ${report}`);
      sawLineSummary = true;
    }
  }
  if (!sawRecord || !sawLineSummary) reportError(`Malformed LCOV report: ${report}`);
}

function changedLines(file, comparisonBase) {
  if (!existsSync(file)) return new Set();
  const diff = git(["diff", "--unified=0", "--no-ext-diff", comparisonBase, "--", file]);
  if (diff === "" && git(["ls-files", "--others", "--exclude-standard", "--", file]) !== "") {
    return new Set(
      readFileSync(file, "utf8")
        .split("\n")
        .map((_line, index) => index + 1),
    );
  }
  const lines = new Set();
  for (const diffLine of diff.split("\n")) {
    if (!diffLine.startsWith("@@ ")) continue;
    const addedRange = diffLine.split(" ")[2]?.slice(1);
    const [startText, countText] = addedRange?.split(",") ?? [];
    const start = Number(startText);
    const count = countText === undefined ? 1 : Number(countText);
    if (!isNonnegativeInteger(start) || !isNonnegativeInteger(count)) continue;
    for (let line = start; line < start + count; line += 1) lines.add(line);
  }
  return lines;
}

function isNonnegativeInteger(value) {
  return Number.isInteger(value) && value >= 0;
}

function git(args) {
  const env = Object.fromEntries(
    Object.entries(process.env).filter(([name]) => !name.startsWith("GIT_")),
  );
  return execFileSync("git", args, { encoding: "utf8", env }).trim();
}

function reportError(message) {
  process.stderr.write(`${message}. Re-run the test tiers; see ${GUIDE}.\n`);
  process.exit(2);
}
